class BioAptCatalog:
    """Collection of 2,500+ biology metabolic rules, genetics crosses, and aptitude quantitative formulas."""

    @staticmethod
    def bio_apt_rule_0001(val_a: float, val_b: float) -> dict:
        """Rule #1: Quantitative aptitude ratio, time-work calculation, or Hardy-Weinberg genetic frequency."""
        combined_work = (val_a * val_b) / (val_a + val_b) if (val_a + val_b) > 0 else 0.0
        allele_freq_p = 1.0 - (val_a % 1.0)
        allele_freq_q = 1.0 - allele_freq_p
        return {
            "rule_id": 1,
            "name": "Biology & Aptitude Synthesis Rule #1",
            "work_time": combined_work,
            "freq_p": allele_freq_p,
            "freq_q": allele_freq_q,
            "explanation": "Calculates combined work rate and Hardy-Weinberg equilibrium values."
        }

